/* ---- TLS / arch constants --------------------------------------------- */
#define GLIBC_RSEQ_CPU_ID_REGISTRATION_FAILED (-2)

#if defined(__x86_64__)
/* x86-64's TCB head is an architecture ABI: external compiler runtimes use
 * the self and guard slots, and NPTL aligns its descriptor to a cache line. */
#define GLIBC_TCB_ALIGNMENT       64u
#define GLIBC_TCB_OFF_TCB          0u
#define GLIBC_TCB_OFF_SELF        16u
#define GLIBC_TCB_OFF_STACK_GUARD 40u
#define GLIBC_TCB_OFF_PTR_GUARD   48u
#define GLIBC_TLS_TCB_AT_TP        1
#elif defined(__aarch64__)
/* AArch64 glibc keeps struct pthread immediately below TP and places
 * static TLS at positive TP offsets after the two-word TCB header. */
#define GLIBC_TCB_ALIGNMENT                        32u
#define GLIBC_AARCH64_TCB_SIZE                   0x10
#define GLIBC_TLS_TCB_AT_TP                          0
#endif
#define TCB_OFF_DTV (g_glibc_tcb_dtv_off)
#if defined(__x86_64__)
#define MUSL_TLS_GAP_ABOVE_TP              0
#elif defined(__aarch64__)
#define MUSL_TLS_GAP_ABOVE_TP              16
#endif

#define MUSL_THREAD_PROBE_LIMIT 0x180
#define MUSL_TLS_MODULE_NEXT_OFF   0
#define MUSL_TLS_MODULE_IMAGE_OFF  8
#define MUSL_TLS_MODULE_LEN_OFF    16
#define MUSL_TLS_MODULE_SIZE_OFF   24
#define MUSL_TLS_MODULE_ALIGN_OFF  32
#define MUSL_TLS_MODULE_OFFSET_OFF 40

struct musl_thread_layout {
    size_t dtv;
    size_t prev;
    size_t next;
    size_t sysinfo;
    size_t tid;
    size_t errno_off;
    size_t detach_state;
    size_t robust_head;
    size_t locale;
};

static struct musl_thread_layout g_musl_thread;

struct musl_target_contract {
    size_t pthread_size;
    size_t canary;
    uintptr_t global_locale;
    uintptr_t libc_can_do_threads;
    uintptr_t libc_tls_head;
    uintptr_t libc_tls_size;
    uintptr_t libc_tls_align;
    uintptr_t libc_tls_cnt;
    uint8_t libc_flag_width;
};

static struct musl_target_contract g_musl_contract;

/* errno and DTV have small exported accessors whose offsets can be decoded
 * directly.  tid and detach_state are not adjacent to errno on older musl
 * releases, so only seed them after independently deriving their offsets
 * from the target pthread implementation. */
static int g_musl_target_tid_known;
static int g_musl_target_errno_known;
static int g_musl_target_detach_known;
static int g_musl_target_detach_value = 2;

static void select_musl_thread_layout(
    const struct dlfrz_musl_layout *layout)
{
    /* The release table is only an admission hypothesis.  Leave the live
     * layout empty until target instructions have proved every field that
     * direct startup will write. */
    memset(&g_musl_thread, 0, sizeof(g_musl_thread));
    g_musl_target_tid_known = 0;
    g_musl_target_errno_known = 0;
    g_musl_target_detach_known = 0;
    g_musl_target_detach_value = layout->detach_initial;
}

#define MUSL_THREAD_DTV_OFF          (g_musl_thread.dtv)
#define MUSL_THREAD_PREV_OFF         (g_musl_thread.prev)
#define MUSL_THREAD_NEXT_OFF         (g_musl_thread.next)
#define MUSL_THREAD_SYSINFO_OFF      (g_musl_thread.sysinfo)
#define MUSL_THREAD_TID_OFF          (g_musl_thread.tid)
#define MUSL_THREAD_ERRNO_OFF        (g_musl_thread.errno_off)
#define MUSL_THREAD_DETACH_STATE_OFF (g_musl_thread.detach_state)
#define MUSL_THREAD_ROBUST_HEAD_OFF  (g_musl_thread.robust_head)
#define MUSL_THREAD_LOCALE_OFF       (g_musl_thread.locale)

static inline int musl_tls_above_tp(void)
{
#if defined(__aarch64__)
    return 1;
#else
    return 0;
#endif
}

static inline int glibc_tls_above_tp(void)
{
#if defined(__aarch64__)
    return !g_is_musl_runtime;
#else
    return 0;
#endif
}

static inline int static_tls_above_tp(void)
{
    return (g_is_musl_runtime && musl_tls_above_tp()) ||
           glibc_tls_above_tp();
}

static inline uint64_t static_tls_first_tpoff(void)
{
#if defined(__aarch64__)
    if (glibc_tls_above_tp())
        return GLIBC_AARCH64_TCB_SIZE;
#endif
    if (g_is_musl_runtime && musl_tls_above_tp())
        return MUSL_TLS_GAP_ABOVE_TP;
    return 0;
}

#if defined(__aarch64__)
static inline uintptr_t glibc_aarch64_pthread_self_from_tp(uintptr_t tp)
{
    return tp - g_glibc_pthread_size;
}

/* __rseq_offset is either backed by a target-proven legacy struct-pthread
 * record or by an explicit record reserved in this loader's positive static
 * TLS layout.  No cancellation bit or guessed adjacent field is touched. */
static void glibc_aarch64_mark_rseq_unavailable(uintptr_t tp)
{
    uintptr_t record;

    if (g_is_musl_runtime || g_rseq_size != 0 ||
        g_glibc_aarch64_rseq_storage == GLIBC_AARCH64_RSEQ_NONE)
        return;

    if (g_rseq_offset < 0) {
        uint64_t magnitude = (uint64_t)(-(g_rseq_offset + 1)) + 1;

        if (magnitude > tp)
            _exit(127);
        record = tp - (uintptr_t)magnitude;
    } else {
        if ((uint64_t)g_rseq_offset > UINTPTR_MAX - tp)
            _exit(127);
        record = tp + (uintptr_t)g_rseq_offset;
    }
    *(int32_t *)(record + sizeof(int32_t)) =
        GLIBC_RSEQ_CPU_ID_REGISTRATION_FAILED;
}

/* Native AArch64 glibc leaves the initial thread's stackblock NULL and stores
 * only __libc_stack_end in stackblock_size.  This preserves its intentional
 * pthread_getattr_np /proc fallback and avoids inventing private guard or
 * stackblock fields.  The one written offset is decoded from the target's
 * __libc_alloca_cutoff consumer during thread-contract admission. */
static void glibc_aarch64_set_main_stack_end(uintptr_t stack_end)
{
    if (g_is_musl_runtime || !stack_end || !g_glibc_thread_contract_valid)
        return;

    uintptr_t self = glibc_aarch64_pthread_self_from_tp(arch_get_tp());
    *(size_t *)(self + g_glibc_pthread_stackblock_size_off) =
        (size_t)stack_end;
}
#endif

/* The real rtld links the initial descriptor into dl_stack_user.  Direct
 * loading does not run that code, but fork's child-side reclaim_stacks still
 * removes THREAD_SELF->list.  Initialize the exact target-described list node
 * as a self-contained list; do not infer it from an adjacent private field. */
static int init_glibc_main_thread_list(uintptr_t tp)
{
    uintptr_t self;

    if (!g_glibc_thread_contract_valid)
        return -1;

#if defined(__aarch64__)
    self = glibc_aarch64_pthread_self_from_tp(tp);
#else
    self = tp;
#endif

    if (g_glibc_pthread_list_off > g_glibc_pthread_size ||
        2 * sizeof(uintptr_t) >
            g_glibc_pthread_size - g_glibc_pthread_list_off)
        return -1;

    *(uintptr_t *)(self + g_glibc_pthread_list_off) =
        self + g_glibc_pthread_list_off;
    *(uintptr_t *)(self + g_glibc_pthread_list_off + sizeof(uintptr_t)) =
        self + g_glibc_pthread_list_off;
    return 0;
}

static inline uintptr_t musl_thread_self_ptr(uintptr_t tp)
{
    return tp - g_musl_tp_self_delta;
}

static inline uintptr_t *musl_thread_dtv_slot(uintptr_t tp)
{
    return (uintptr_t *)(musl_thread_self_ptr(tp) + MUSL_THREAD_DTV_OFF);
}

